struct Tidword {
  union {
    uint64_t obj_;
    struct {
      bool lock : 1;
      bool latest : 1;
      bool absent : 1;
      uint64_t tid : 29;
      uint64_t epoch : 32;
    };
  };

  Tidword() : obj_(0){};

  bool operator==(const Tidword& right) const { return obj_ == right.obj_; }

  bool operator!=(const Tidword& right) const { return !operator==(right); }

  bool operator<(const Tidword& right) const { return this->obj_ < right.obj_; }
};

class Tuple {
public:
  alignas(CACHE_LINE_SIZE) Tidword tidword_;
  TupleBody body_;

  Tuple() {}

  void init([[maybe_unused]] size_t thid, TupleBody&& body,
            [[maybe_unused]] void* p) {
    // for initializer
    tidword_.epoch = 1;
    tidword_.latest = true;
    tidword_.absent = false;
    tidword_.lock = false;
    body_ = std::move(body);
  }

  void init(TupleBody&& body) {
    tidword_.absent = true;
    tidword_.lock = true;
    body_ = std::move(body);
  }
};

