  LogHeader loadhd;
  LogRecord logrec;

  loadfile.read((void*) &loadhd, sizeof(LogHeader));
  cout << "chkSum_ : " << loadhd.chkSum_ << endl;
  cout << "logRecNum_ : " << loadhd.logRecNum_ << endl;

